using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer;

/// <summary>
/// MCP tool classes are discovered via [McpServerToolType] on the class
/// and [McpServerTool] on each method. The SDK instantiates the class
/// per-call using DI — constructor parameters are resolved from the host's
/// service container.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _http;

    // HttpClient is injected via DI (registered with AddHttpClient below)
    public WeatherTools(HttpClient http)
    {
        _http = http;
    }

    [McpServerTool, Description("Get current weather for a city using wttr.in")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'Seattle'")] string city,
        CancellationToken cancellationToken = default)
    {
        var response = await _http.GetAsync(
            $"https://wttr.in/{Uri.EscapeDataString(city)}?format=j1",
            cancellationToken);

        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync(cancellationToken);
        return json;
    }

    [McpServerTool, Description("Get a short one-line weather summary for a city")]
    public async Task<string> GetWeatherSummary(
        [Description("City name")] string city,
        CancellationToken cancellationToken = default)
    {
        // wttr.in format=3 returns something like "Seattle: ⛅️ +12°C"
        var response = await _http.GetStringAsync(
            $"https://wttr.in/{Uri.EscapeDataString(city)}?format=3",
            cancellationToken);

        return response.Trim();
    }
}

